import{z as i,x as s,o as e,c as d,q as t,j as n,D as A,d as a,s as l,S as o,b as B}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"移仓的执行","description":"","frontmatter":{"title":"移仓的执行","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ft-roll-execution.md","filePath":"quant/ft-roll-execution.md","lastUpdated":1791063341000}'),p={name:"quant/ft-roll-execution.md"};function C(m,E,u,D,h,F){const r=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=t('<h1 id="移仓的执行" tabindex="-1">移仓的执行 <a class="header-anchor" href="#移仓的执行" aria-label="Permalink to &quot;移仓的执行&quot;">​</a></h1><div class="epigraph"><p>移仓不是两笔交易，是一笔跨期交易的两条腿；把它拆开下的每一刻，你都在赌一条本想中性持有的价差。</p><footer>—— 据 Almgren and Chriss, Journal of Risk, 2000 与 Harris, Trading and Exchanges, 2003 整理；滚仓窗流动性的证据见 Mou, 2011 与 Bessembinder, Carrion, Tuttle and Venkataraman, JFE, 2016</footer></div><p><a href="/quant/ft-roll-cost-modeling">上一课</a>把展期成本写成期望与方差两项：价差、冲击、择时风险。缺口是把账单变成动作：同一张成本表下，一次成交、分腿、多日摊薄、阈值触发，哪个方案真的落在表上？执行层一旦随手，成本模型的精度只是自我安慰。本课写移仓怎么下：方案族、腿的次序、与基准的偏差记录。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>方案族有三支。其一，日历价差单：把卖近买远作为一笔价差单报进交易所，成交原子，交易所常对构成价差的持仓给保证金减免；代价是价差单的对手薄，大额挂单会挂在书里等波动。其二，分腿：两腿各自下单，可吃各自的深度，但在两腿成交的间隔里，仓位带价差敞口——你赌的是价差不动。其三，多日摊薄：把窗口拉长降冲击，代价是上一课的择时方差按 \\(\\sqrt{\\tau}\\) 增长。</p><p><span class="marginnote">直觉类比：三支方案像搬钢琴下楼——价差单是请搬家公司一次抬走，整件不出岔子但排期慢；分腿是先推琴身再搬琴凳，各自灵活，可两件东西中途可能「分家」；摊薄是分五天搬，每天轻松些，但夜长梦多。</span></p><p>错在哪：先动厚腿，薄腿的价格等着你，价差在你腿间跑掉；全部挤在官方指数日成交，与被动流同向抢宽度——<a href="/quant/roll-volume-oi">展期成交量与持仓</a>已证明窗口内供给弹性决定冲击大小；没有停板预案，一条腿被锁在涨跌停里，价差仓位瞬间变方向仓位。</p><h3 id="腿的次序与触发" tabindex="-1">腿的次序与触发 <a class="header-anchor" href="#腿的次序与触发" aria-label="Permalink to &quot;腿的次序与触发&quot;">​</a></h3><p>分腿时先走难走的腿：深度薄、宽度宽的那条先成交，厚腿随后用限价或价差触发条件收。理由是信息不对称的方向——薄腿的成交对价差的冲击大，先锁它，剩下的敞口在容易对冲的一侧。多日摊薄配阈值触发：价差相对上一课的公允参照便宜时加速、贵时减速，把窗口的形状交给市场定价，而不是均匀分配。每一步记实现缺口：相对基准（如官方日的价差结算价，或窗口起点中间价）的差，分日、分腿入账。</p><p><span class="marginnote">数字实例：择时方差按 \\(\\sqrt{\\tau}\\) 增长——摊薄窗口从 1 天拉长到 5 天，冲击下降，但方差项放大 \\(\\sqrt{5}\\approx 2.2\\) 倍。若日历价差日波动 20 个基点，5 天窗的风险成本按约 2.2 倍去权衡，再与省下的冲击比大小，才谈得上「最优」。</span></p><p><span class="marginnote">交易所价差单的保证金减免不是免费的流动性：价差单成交慢，挂着等成交期间你的移仓并未完成，截止日约束（第一课的日历）仍在收紧。挂价差单可以，但要在日历上预留「未成交则转分腿」的降级路径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把方案写成决策规则而不是当天的心情。输入：名义规模相对窗口深度、成本表、截止日、停板规则。输出：方案与参数——摊薄几日、每日参与率上限、价差触发的带宽、转分腿的触发价。规模小且价差单流动性够，价差单一次成交；规模大，摊薄加触发；截止日逼近且未完成，转入市价保完成——确定性与成本的取舍在截止日前面让路。事后核对账：期望成本（模型）对实现缺口（账本），偏差进入成本表的再校准，这正是上一课留的接口。</p>',13)),(e(),n(o,null,{default:A(()=>[l(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%90%8D%E4%B9%89%E3%80%81%E6%88%90%E6%9C%AC%E8%A1%A8%E3%80%81%E6%88%AA%E6%AD%A2%E6%97%A5%E3%80%81%E5%81%9C%E6%9D%BF%E8%A7%84%E5%88%99%22%5D%20--%3E%20Q1%7B%22%E8%A7%84%E6%A8%A1%E7%9B%B8%E5%AF%B9%E6%B7%B1%E5%BA%A6%E5%B0%8F%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%E6%98%AF%7C%20SPRD%5B%22%E6%8C%82%E6%97%A5%E5%8E%86%E4%BB%B7%E5%B7%AE%E5%8D%95%22%5D%0A%20%20Q1%20--%3E%7C%E5%90%A6%7C%20STAG%5B%22%E5%A4%9A%E6%97%A5%E6%91%8A%E8%96%84%20%2B%20%E4%BB%B7%E5%B7%AE%E8%A7%A6%E5%8F%91%22%5D%0A%20%20SPRD%20--%3E%7C%22%E6%88%AA%E6%AD%A2%E6%97%A5%E8%BF%91%E6%9C%AA%E6%88%90%E4%BA%A4%22%7C%20LEG%5B%22%E9%99%8D%E7%BA%A7%EF%BC%9A%E5%88%86%E8%85%BF%EF%BC%8C%E8%96%84%E8%85%BF%E5%85%88%E8%B5%B0%22%5D%0A%20%20STAG%20--%3E%7C%22%E6%88%AA%E6%AD%A2%E6%97%A5%E8%BF%91%E6%9C%AA%E5%AE%8C%E6%88%90%22%7C%20MKT%5B%22%E8%BD%AC%E5%B8%82%E4%BB%B7%E4%BF%9D%E5%AE%8C%E6%88%90%22%5D%0A%20%20SPRD%20--%3E%20REC%5B%22%E8%AE%B0%E5%AE%9E%E7%8E%B0%E7%BC%BA%E5%8F%A3%20vs%20%E5%9F%BA%E5%87%86%22%5D%0A%20%20LEG%20--%3E%20REC%0A%20%20MKT%20--%3E%20REC%0A%20%20REC%20--%3E%20CAL%5B%22%E5%9B%9E%E5%A1%AB%E6%88%90%E6%9C%AC%E8%A1%A8%E5%86%8D%E6%A0%A1%E5%87%86%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("摊薄降冲击的机制是市场深度的自我修复需要时间：参与率低，做市与套利者有间隙回补存货，你的临时冲击不转成永久冲击；代价是敞口时间变长，方差按执行期平方根增长——Almgren 与 Chriss 的最优解正是这对拉扯在给定风险厌恶下的驻点。薄腿先走的机制同上：冲击沿流动性差的腿传导进价差，先成交它等于把不可控的部分先定价。与指数错日的机制是"),B("a",{href:"/quant/roll-volume-oi"},"展期成交量与持仓"),a("的供给侧：别人必须走官方日，你不必，你提前或推后，就在向同向拥挤者卖流动性，冲击成本的一部分变成你的收入。")],-1)),(e(),n(o,null,{default:A(()=>[l(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20START%5B%22%E5%88%86%E8%85%BF%E7%A7%BB%E4%BB%93%EF%BC%9A%E4%B8%A4%E6%9D%A1%E8%85%BF%E9%83%BD%E8%A6%81%E6%88%90%E4%BA%A4%22%5D%20--%3E%20RIGHT%5B%22%E5%85%88%E8%B5%B0%E8%96%84%E8%85%BF%EF%BC%9A%E9%9A%BE%E8%B5%B0%E7%9A%84%E9%82%A3%E6%9D%A1%22%5D%0A%20%20RIGHT%20--%3E%20R1%5B%22%E8%96%84%E8%85%BF%E5%86%B2%E5%87%BB%E5%85%88%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20RIGHT%20--%3E%20R2%5B%22%E5%89%A9%E4%BD%99%E6%95%9E%E5%8F%A3%E8%90%BD%E5%9C%A8%E5%AE%B9%E6%98%93%E6%94%B6%E7%9A%84%E4%B8%80%E4%BE%A7%22%5D%0A%20%20R1%20--%3E%20OK%5B%22%E5%8E%9A%E8%85%BF%E9%99%90%E4%BB%B7%E6%85%A2%E6%94%B6%EF%BC%9A%E7%BC%BA%E5%8F%A3%E5%8F%AF%E6%8E%A7%22%5D%0A%20%20R2%20--%3E%20OK%0A%20%20START%20--%3E%20WRONG%5B%22%E5%85%88%E8%B5%B0%E5%8E%9A%E8%85%BF%EF%BC%9A%E9%A1%BA%E6%89%8B%E7%9A%84%E9%82%A3%E6%9D%A1%22%5D%0A%20%20WRONG%20--%3E%20W1%5B%22%E8%96%84%E8%85%BF%E8%BF%98%E6%82%AC%E7%9D%80%EF%BC%9A%E4%BB%B7%E5%B7%AE%E5%BC%80%E5%A7%8B%E8%B7%91%22%5D%0A%20%20W1%20--%3E%20W2%5B%22%E8%A2%AB%E8%BF%AB%E8%BF%BD%E4%BB%B7%EF%BC%9A%E4%BB%98%E5%87%BA%E4%BB%B7%E5%B7%AE%E8%B7%91%E6%8E%89%E7%9A%84%E7%BC%BA%E5%8F%A3%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">常见误区：以为「保完成」总能做到。停板制度下一条腿被锁死，价差仓位瞬间变成方向仓位。预案要提前写明锁腿后用什么对冲（相关品种或期权），而不是等到那天现想。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>跨交易所、跨时区的品种（伦敦金属对 COMEX、境外指数对中金所）价差单不可用，分腿是常态，腿间风险要单独限额。停板与涨跌停制度下，「保完成」可能做不到，预案要写明锁腿后的对冲工具（相关品种或期权）。价差保证金减免在交割月会被取消，别按窗内保证金外推。纸面回测不能假设价差单按报价全成：价差单的成交率本身是待估参数。本课执行的是给定状态下的方案；库存与仓单如何改变方案，下一课再探。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>移仓方案族三支：日历价差单、分腿、多日摊薄；原子性、深度、择时方差三者换手。</li><li>薄腿先走，厚腿收尾；摊薄配价差触发，窗口形状交给市场定价。</li><li>每次移仓记实现缺口并回填成本表，执行与建模闭环。</li><li>截止日约束优先于成本优化：临近时确定性让成本让路，停板预案先写好。</li><li>出处：Almgren and Chriss, <em>Journal of Risk</em>, 2000；Harris, <em>Trading and Exchanges</em>, 2003；Mou, 2011；Bessembinder, Carrion, Tuttle and Venkataraman, <em>JFE</em>, 2016。</li></ul>',5))])}const T=i(p,[["render",C]]);export{f as __pageData,T as default};
